-- layouts
select public.save_flat('{"rooms": {"liv": {"w": "wall2", "f": "floor1", "items": [["sofa", 300, 0, 0], ["lamp", 200, 0, 0], ["lamp", 600, 0, 1], ["rug", 400, 1, 0]]}, "bed": {"w": "wall0", "f": "floor0", "items": [["bed", 300, 0, 0]]}}, "show": {"fish": ["SARDINE"]}}'::jsonb);
