set role authenticated; select set_config('test.uid', 'aaaaaaaa-0000-0000-0000-000000000001', false);
do $$ begin perform count(*) from public.apartments; raise notice 'FAIL read the apartments table directly'; exception when insufficient_privilege then raise notice 'PASS the table is only read through the RPCs'; end $$;
