do $$ begin perform public.save_flat('{"rooms": {"liv": {"items": [["tv", 1, 0, 0]]}}}'::jsonb); raise notice 'FAIL placed a tv never bought'; exception when raise_exception then raise notice 'PASS unowned furniture refused'; end $$;
